CREATE TABLE pgseqname_1.t(id integer," X " boolean);
INSERT INTO pgseqname_1.t VALUES(7,true);
CREATE TABLE pgseqname_1.identity_table(id bigint GENERATED ALWAYS AS IDENTITY);
CREATE TABLE pgseqname_1.owned_elsewhere(id integer);
ALTER TABLE pgseqname_1.owned_elsewhere OWNER TO pgseqname_1_owner;
CREATE TABLE pgseqname_1_other.t(id integer);
CREATE VIEW pgseqname_1.v AS SELECT id FROM pgseqname_1.t;
CREATE TABLE pgseqname_1_occupied.guard(id integer);
CREATE SEQUENCE pgseqname_1.s AS smallint INCREMENT BY 2 MINVALUE 1 MAXVALUE 99 START WITH 7 CACHE 3 OWNED BY pgseqname_1.t.id;
CREATE SEQUENCE pgseqname_1.guard START 7;
CREATE TABLE pgseqname_1.receipt AS SELECT c.oid,c.relname,c.relnamespace,c.relowner,s.seqtypid,s.seqstart,s.seqincrement,s.seqmin,s.seqmax,s.seqcache,s.seqcycle,array(SELECT d.refobjid::text||':'||d.refobjsubid||':'||d.deptype::text FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.refclassid='pg_class'::regclass ORDER BY d.refobjid,d.refobjsubid,d.deptype) AS owners FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid WHERE c.relnamespace IN ('pgseqname_1'::regnamespace,'pgseqname_1_other'::regnamespace,'pgseqname_1_occupied'::regnamespace)

