CREATE TABLE pgseq_25.identity_table(id bigint GENERATED ALWAYS AS IDENTITY);
CREATE TABLE pgseq_25.owned_elsewhere(id integer);
ALTER TABLE pgseq_25.owned_elsewhere OWNER TO pgseq_25_owner;
CREATE TABLE pgseq_25_other.t(id integer);
CREATE VIEW pgseq_25.v AS SELECT id FROM pgseq_25.t;
CREATE SEQUENCE pgseq_25.s AS smallint INCREMENT BY 2 MINVALUE 1 MAXVALUE 99 START WITH 7 CACHE 3 OWNED BY pgseq_25.t.id;
CREATE SEQUENCE pgseq_25.guard START 7;
CREATE TABLE pgseq_25.receipt AS SELECT c.oid,c.relname,c.relnamespace,c.relowner,s.seqtypid,s.seqstart,s.seqincrement,s.seqmin,s.seqmax,s.seqcache,s.seqcycle,array(SELECT d.refobjid::text||':'||d.refobjsubid||':'||d.deptype::text FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.refclassid='pg_class'::regclass ORDER BY d.refobjid,d.refobjsubid,d.deptype) AS owners FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid WHERE c.relnamespace='pgseq_25'::regnamespace

